// 0.52.0 — an existing platform firewall gains the Postgres drivers in platform:web and platform:shared.
//
// The shapes it meets: the firewall exactly as 0.50.0 through 0.51.3 wrote it on an Angular workspace
// (0.52.0-stock-firewall/, generated by running insertPlatformFirewall from 6b85dd69; 6dab55f5's output is
// byte-identical, so one file stands for the range), that firewall as a project reformatted or edited it, a workspace
// with no firewall, and the 0.49 shape on the upstream ladder, where 0.50.0 writes the live table first.
//
// It reads `platformConstraints` as its marker, and every release carrying that name shipped the one stock shape above,
// so there is no earlier shape to list under historicalShapes. The table's own drift alarm is in
// tools/test-generators/cases/platform-firewall-seam.mjs, because it needs the compiled table.
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const CONFIG = 'eslint.config.mjs';
const STOCK = readFileSync(join(dirname(fileURLToPath(import.meta.url)), '0.52.0-stock-firewall', CONFIG), 'utf8');
const DRIVERS = ['pg', 'pg-native', 'pg-pool', 'pg-cursor', 'pg-query-stream', 'pg-promise', 'postgres', 'slonik'];
const BANS = DRIVERS.flatMap((d) => [d, `${d}/*`]);

/** The ban list of one constraint, as text — enough to assert on, in any style the fixtures use. */
const listOf = (config, tag) => {
  const at = config.indexOf(`sourceTag: '${tag}'`);
  if (at < 0) return null;
  const open = config.indexOf('bannedExternalImports', at);
  const next = config.indexOf('sourceTag:', at + 1);
  if (open < 0 || (next >= 0 && open > next)) return null;
  const end = config.indexOf(']', open);
  return [...config.slice(open, end).matchAll(/'([^']+)'/g)].map((m) => m[1]);
};
const swap = (from, to) => {
  if (!STOCK.includes(from)) throw new Error(`the stock firewall no longer holds: ${from}`);
  return STOCK.replace(from, to);
};

// The 0.49 shape, as 0.50.0's own case carries it (git show 8a017ae, addPlatformBoundaries).
const OLD_FIREWALL = `import nx from '@nx/eslint-plugin';

export default [
  ...nx.configs['flat/base'],
  {
    files: ['**/*.ts'],
    rules: {
      '@nx/enforce-module-boundaries': [
        'error',
        {
          enforceBuildableLibDependency: true,
          allow: [],
          depConstraints: [
            {
              sourceTag: 'platform:web',
              bannedExternalImports: ['firebase-admin', 'firebase-admin/*', 'firebase-functions', 'firebase-functions/*'],
            },
            {
              sourceTag: 'platform:server',
              bannedExternalImports: ['firebase', 'firebase/*', '@angular/*'],
            },
          ],
        },
      ],
    },
  },
];
`;

export default {
  name: '0.52.0 · ban-postgres-drivers-from-web',
  ladder: ['0.52.0/ban-postgres-drivers-from-web'],
  cases: [
    {
      name: 'the stock firewall: web and shared gain every driver at the end of their lists, one per line; server and the rest of the file are untouched; the leak is explained',
      setup: (tree) => tree.write(CONFIG, STOCK),
      expect: (tree, t, logs) => {
        const config = t.read(CONFIG);
        const web = listOf(STOCK, 'platform:web');
        const shared = listOf(STOCK, 'platform:shared');
        t.equal(listOf(config, 'platform:web'), [...web, ...BANS], 'web: its own list, then the drivers');
        t.equal(listOf(config, 'platform:shared'), [...shared, ...BANS], 'shared: its own list, then the drivers');
        t.equal(listOf(config, 'platform:server'), listOf(STOCK, 'platform:server'), 'server keeps the drivers allowed');
        t.has(CONFIG, "      'express/*',\n      'pg',\n      'pg/*',\n");
        const withoutBans = config.replace(new RegExp(`\\n {6}'(${DRIVERS.join('|')})(/\\*)?',`, 'g'), '');
        t.ok(withoutBans === STOCK, 'nothing but the 32 ban lines changed');
        t.ok(logs.some((l) => /real leak/.test(l)), 'a lint failure is called what it is');
        t.ok(logs.some((l) => l.includes('platform:web now bans pg, pg/*')), 'what changed is named');
      },
    },
    {
      name: 'a project that already bans some keeps them: only what no entry covers is added, a wider pattern counts, its own bans stay',
      setup: (tree) => tree.write(CONFIG, swap("      'express/*',\n    ],\n  },\n  {\n    sourceTag: 'platform:server',", "      'express/*',\n      'pg',\n      'postgres*',\n      'mysql2',\n    ],\n  },\n  {\n    sourceTag: 'platform:server',")),
      expect: (tree, t) => {
        const web = listOf(t.read(CONFIG), 'platform:web');
        t.equal(web.filter((b) => b === 'pg').length, 1, 'pg is not listed twice');
        t.ok(web.includes('pg/*') && web.includes('slonik/*'), 'the missing ones arrive');
        t.ok(!web.includes('postgres') && !web.includes('postgres/*'), 'postgres* already covers postgres and its subpaths');
        t.ok(web.includes('mysql2'), "the project's own ban stays");
      },
    },
    {
      name: 'a list on one line stays on one line; a list with no trailing comma gets one; a comment trailing the last entry stays with it',
      setup: (tree) => {
        const inline = swap(
          /sourceTag: 'platform:web',[\s\S]*?\],\n {2}\},/.exec(STOCK)[0],
          "sourceTag: 'platform:web',\n    onlyDependOnLibsWithTags: ['platform:web', 'platform:shared'],\n    bannedExternalImports: ['express'],\n  },",
        );
        const shared = /sourceTag: 'platform:shared',[\s\S]*?\],\n {2}\},/.exec(inline)[0];
        tree.write(CONFIG, inline.replace(shared, "sourceTag: 'platform:shared',\n    onlyDependOnLibsWithTags: ['platform:shared'],\n    bannedExternalImports: [\n      'express' // ours\n    ],\n  },"));
      },
      expect: (tree, t) => {
        t.has(CONFIG, "bannedExternalImports: ['express', 'pg', 'pg/*',");
        t.has(CONFIG, "'slonik/*'],");
        t.has(CONFIG, "      'express', // ours\n      'pg',\n");
        t.has(CONFIG, "      'slonik/*'\n    ],");
      },
    },
    {
      name: 'an empty list is filled',
      setup: (tree) => tree.write(CONFIG, swap(/sourceTag: 'platform:web',[\s\S]*?\],\n {2}\},/.exec(STOCK)[0], "sourceTag: 'platform:web',\n    onlyDependOnLibsWithTags: ['platform:web', 'platform:shared'],\n    bannedExternalImports: [],\n  },")),
      expect: (tree, t) => t.equal(listOf(t.read(CONFIG), 'platform:web'), BANS, 'web holds the drivers'),
    },
    {
      name: 'a dropped constraint is reported, and the rest is still done',
      setup: (tree) => {
        const noShared = swap(/ {2}\{\n {4}sourceTag: 'platform:shared',[\s\S]*?\],\n {2}\},\n/.exec(STOCK)[0], '');
        tree.write(CONFIG, noShared);
      },
      expect: (tree, t, logs) => {
        t.ok(logs.some((l) => /platform:shared has no constraint in platformConstraints, so these were not added: pg, pg\/\*/.test(l)), `the dropped constraint is named: ${logs.join(' | ')}`);
        t.ok(listOf(t.read(CONFIG), 'platform:web').includes('pg'), 'web still gains them');
      },
    },
    {
      name: 'a ban list that is not an array literal is left and reported',
      setup: (tree) => {
        const web = /sourceTag: 'platform:web',[\s\S]*?\],\n {2}\},/.exec(STOCK)[0];
        tree.write(CONFIG, `const OUR_BANS = ['express'];\n${swap(web, "sourceTag: 'platform:web',\n    onlyDependOnLibsWithTags: ['platform:web', 'platform:shared'],\n    bannedExternalImports: OUR_BANS,\n  },")}`);
      },
      expect: (tree, t, logs) => {
        t.has(CONFIG, 'bannedExternalImports: OUR_BANS,');
        t.ok(logs.some((l) => /platform:web has a `bannedExternalImports` that is not an array literal/.test(l)), `reported: ${logs.join(' | ')}`);
      },
    },
    {
      name: 'platformConstraints built by an expression: untouched, and said so with the list',
      setup: (tree) => tree.write(CONFIG, `const platformConstraints = buildConstraints();\nexport default [];\n`),
      expect: (tree, t, logs) => {
        t.ok(t.read(CONFIG) === `const platformConstraints = buildConstraints();\nexport default [];\n`, 'byte-identical');
        t.ok(logs.some((l) => /not an array literal/.test(l) && l.includes('pg-native/*')), `reported: ${logs.join(' | ')}`);
      },
    },
    {
      name: 'no firewall: the config is not given one',
      setup: (tree) => tree.write(CONFIG, "import nx from '@nx/eslint-plugin';\n\nexport default [...nx.configs['flat/base']];\n"),
      expect: (tree, t, logs) => {
        t.hasNot(CONFIG, 'pg');
        t.ok(!logs.length, `nothing to say: ${logs.join(' | ')}`);
      },
    },
    {
      name: 'no ESLint config at all: nothing',
      setup: () => {},
      expect: (tree, t) => t.missing(CONFIG),
    },
    {
      name: 'a 0.49 shape the 0.50.0 rung could not upgrade: left, and reported with the list',
      setup: (tree) => tree.write(CONFIG, OLD_FIREWALL),
      expect: (tree, t, logs) => {
        t.ok(t.read(CONFIG) === OLD_FIREWALL, 'byte-identical');
        t.ok(logs.some((l) => /carries no `platformConstraints`/.test(l) && l.includes('slonik/*')), `reported: ${logs.join(' | ')}`);
      },
    },
    {
      name: 'the upstream ladder: 0.50.0 writes the live table, so a 0.49 project has the drivers once and this rung has nothing to add',
      ladder: ['0.50.0/close-the-platform-firewall', '0.52.0/ban-postgres-drivers-from-web'],
      setup: (tree) => tree.write(CONFIG, OLD_FIREWALL),
      expect: (tree, t, logs) => {
        const config = t.read(CONFIG);
        for (const tag of ['platform:web', 'platform:shared']) {
          for (const ban of BANS) t.equal(listOf(config, tag).filter((b) => b === ban).length, 1, `${tag} bans ${ban} once`);
        }
        t.ok(!listOf(config, 'platform:server').includes('pg'), 'server keeps pg allowed');
        t.ok(!logs.some((l) => l.includes('0.52.0/ban-postgres-drivers-from-web')), `this rung said nothing: ${logs.filter((l) => l.includes('0.52.0')).join(' | ')}`);
      },
    },
  ],
};
